// Autogenerated categories are labelled with the folder name (backend, architecture...).
// This generator turns them into readable chapter titles:
// 1. a folder with an index page (README.md) takes that page's title;
// 2. otherwise a known folder name is translated for the current locale;
// 3. otherwise the folder name stays.
// Each category also gets a key from its folder path, because the same folder name
// (architecture, diagrams...) appears under several areas and translation keys must be unique.

export const folderLabels = {
  es: {
    architecture: 'Arquitectura',
    backend: 'Backend',
    business: 'Modelo de negocio',
    data: 'Datos',
    design: 'Diseño',
    development: 'Desarrollo',
    diagrams: 'Diagramas',
    'frontend-mobile': 'App móvil',
    'frontend-web': 'Web',
    'getting-started': 'Primeros pasos',
    governance: 'Gobierno',
    guides: 'Guías',
    infra: 'Infraestructura',
    operations: 'Operación',
    presentation: 'Presentación',
    project: 'Proyecto',
    quality: 'Calidad de software',
    security: 'Seguridad',
    shared: 'Compartido',
    testing: 'Pruebas',
    'use-cases': 'Casos de uso',
  },
  en: {
    architecture: 'Architecture',
    backend: 'Backend',
    business: 'Business model',
    data: 'Data',
    design: 'Design',
    development: 'Development',
    diagrams: 'Diagrams',
    'frontend-mobile': 'Mobile app',
    'frontend-web': 'Web',
    'getting-started': 'Getting started',
    governance: 'Governance',
    guides: 'Guides',
    infra: 'Infrastructure',
    operations: 'Operations',
    presentation: 'Presentation',
    project: 'Project',
    quality: 'Software quality',
    security: 'Security',
    shared: 'Shared',
    testing: 'Testing',
    'use-cases': 'Use cases',
  },
};

// Reading order, like a book: areas first, then the chapters inside each area.
// Folders not listed keep Docusaurus order after the listed ones.
// Names shared by several levels (architecture, diagrams...) keep a sensible order at each level.
// At the root the book goes from the general to the technical: manuals and videos, modules,
// system architecture, each platform, local development, diagrams, URLs, schedule and governance.
// The project overview opens the book, followed by the oral presentation; the business model
// follows the modules, and security and quality follow the infrastructure.
// Inside an area, architecture comes before data, use cases, diagrams and testing.
export const folderOrder = [
  'project',
  'presentation',
  'manuals',
  'videos',
  'modules',
  'business',
  'architecture',
  'backend',
  'frontend-web',
  'frontend-mobile',
  'infra',
  'security',
  'quality',
  'shared',
  'getting-started',
  'data',
  'use-cases',
  'diagrams',
  'testing',
  'guides',
  'development',
  'operations',
  'design',
  'technologies',
  'important-urls',
  'gantt',
  'governance',
  // Product modules (docs/<lang>/modules), from account and catalog to administration.
  'users',
  'legal',
  'wines',
  'wineries',
  'reviews',
  'cellar',
  'community',
  'events',
  'payments',
  'wine-routes',
  'sharing',
  'notifications',
  'ai',
  'support',
  'partner',
  'admin',
];

// Pages come before folders, so a level opens with its own pages (the root index first).
const rank = folder => {
  if (folder === undefined) {
    return -1;
  }
  const position = folderOrder.indexOf(folder);
  return position === -1 ? folderOrder.length : position;
};

/** Docusaurus reads translated docs from @site/i18n/<locale>/...; the default locale is es. */
export function localeOf(docs) {
  const source = docs.find(doc => typeof doc.source === 'string')?.source ?? '';
  return source.match(/^@site\/i18n\/([^/]+)\//)?.[1] ?? 'es';
}

// Docusaurus already labels a folder that has an index page with that page's title,
// so the folder name comes from the index page id (`<folder>/README`).
const folderOf = item => {
  if (item.type !== 'category') {
    return undefined;
  }
  return item.link?.type === 'doc' ? item.link.id.split('/').at(-2) : item.label;
};

export function labelCategories(items, docs, locale = localeOf(docs), parents = []) {
  const titles = new Map(docs.map(doc => [doc.id, doc.title]));
  const labels = folderLabels[locale] ?? {};
  const ordered = items
    .map((item, index) => ({ item, index, folder: folderOf(item) }))
    .sort((a, b) => rank(a.folder) - rank(b.folder) || a.index - b.index);
  return ordered.map(({ item, folder }) => {
    if (item.type !== 'category') {
      return item;
    }
    const path = [...parents, folder];
    const title = item.link?.type === 'doc' ? titles.get(item.link.id) : undefined;
    return {
      ...item,
      key: path.join('/'),
      label: title ?? labels[folder] ?? folder,
      items: labelCategories(item.items, docs, locale, path),
    };
  });
}

export default async function chapterLabels({ defaultSidebarItemsGenerator, ...args }) {
  const items = await defaultSidebarItemsGenerator(args);
  return labelCategories(items, args.docs);
}
